function changeAnimeBySide(timing, battleChara, animeNo)
    local fixedAnimeNo = animeNo

    -- 敵側の場合のみアニメ番号を反転
    if _IS_PLAYER_SIDE_ == 0 then
        if animeNo >= 100 then
            fixedAnimeNo = animeNo - 100;
        else
            fixedAnimeNo = animeNo + 100;
        end
    end

    changeAnime(timing, battleChara, fixedAnimeNo)
end
